package store.cadera.cdrjobs.listener;
import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.persistence.PersistentDataType;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.api.*;import store.cadera.cdrjobs.api.event.ProfessionActionEvent;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import java.util.*;
public final class HunterListener implements Listener{private final CdrJobsPlugin plugin;private final ProgressionService progression;private final HunterService hunter;private final LevelService levels;private final NamespacedKey origin;private Map<EntityType,Integer>xp=new EnumMap<>(EntityType.class);public HunterListener(CdrJobsPlugin p,ProgressionService pr,HunterService h,LevelService l){plugin=p;progression=pr;hunter=h;levels=l;origin=new NamespacedKey(p,"hunter_spawn_origin");refreshXpMap();}public void refreshXpMap(){Map<EntityType,Integer>m=new EnumMap<>(EntityType.class);ConfigurationSection s=plugin.getConfig().getConfigurationSection("hunter.xp");if(s!=null)for(String k:s.getKeys(false))try{m.put(EntityType.valueOf(k.toUpperCase()),s.getInt(k));}catch(Exception ignored){}xp=m;}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void spawn(CreatureSpawnEvent e){e.getEntity().getPersistentDataContainer().set(origin,PersistentDataType.STRING,e.getSpawnReason().name());}@EventHandler(priority=EventPriority.MONITOR)public void death(EntityDeathEvent e){if(!plugin.getConfig().getBoolean("hunter.enabled",true))return;Player p=e.getEntity().getKiller();if(p==null)return;Integer base=xp.get(e.getEntityType());if(base==null)return;String o=e.getEntity().getPersistentDataContainer().get(origin,PersistentDataType.STRING);if(o!=null&&((plugin.getConfig().getBoolean("hunter.anti-exploit.exclude-spawner",true)&&o.equals("SPAWNER"))||(plugin.getConfig().getBoolean("hunter.anti-exploit.exclude-breeding",true)&&o.equals("BREEDING"))))return;boolean danger=hunter.dangerous(e.getEntityType());long time=p.getWorld().getTime();hunter.recordKill(p,danger,time>=13000&&time<=23000);plugin.getServer().getPluginManager().callEvent(new ProfessionActionEvent(p,JobType.HUNTER,ProfessionActionType.KILL_ENTITY,1));long amount=hunter.applyXp(p,Math.max(1,Math.round(base*Math.max(0,plugin.getConfig().getDouble("hunter.xp-multiplier",1)))),danger);JobProgress pr=progression.addXp(p,JobType.HUNTER,amount);if(plugin.getConfig().getBoolean("settings.actionbar-xp",true)){long req=levels.xpRequiredForNextLevel(pr.level());p.sendActionBar(Component.text(pr.level()>=levels.maxLevel()?"✦ Bloodfang Stalker Lv."+levels.maxLevel()+" • MAX":"✦ Bloodfang +"+amount+" XP • Lv."+pr.level()+" • "+pr.xp()+"/"+req));}}
}
